import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// `n` lines whose prices add up to `subtotal`.
const lines = (n, subtotal) =>
  Array.from({ length: n }, () => ({ price: subtotal / n, qty: 1 }));

test('customer discount is applied once', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
  assert.equal(total(lines(9, 9000), 0.1), 8100);
});

test('bulk discount is applied once, after the customer discount', () => {
  assert.equal(total(lines(10, 10000), 0.1), 8550);
});

test('zero discount rate leaves the total unchanged', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0), 1000);
  assert.equal(total(lines(9, 9000), 0), 9000);
  assert.equal(total(lines(10, 10000), 0), 9500);
  assert.equal(total(lines(10, 10000)), 9500);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
